const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const cf=($('Resolve Base').first().json.fields)||{};
const att=Array.isArray(f['Attachment'])?f['Attachment']:[];
if(!att.length){ throw new Error('Launch record '+rec.id+' has no Attachment CSV.'); }
const rawTid=((f['Table ID']||f['Target']||'')+'').trim();
const m=rawTid.match(/tbl[A-Za-z0-9]{14}/);
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Build name': ((f['Build name']||'')+'').trim(),
  'Existing Table ID': m?m[0]:rawTid,
  'Domains Table ID': ((f['Domains Table ID']||'')+'').trim(),
  'Tag': ((f['Tag']||'')+'').trim(),
  '_csvName': (att[0]&&att[0].filename)||'launch.csv',
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];

const params=$('Launch Params').first().json;
const bin=$input.first().binary||{};
const data=bin.data||Object.values(bin)[0];
if(!data){ throw new Error('Download CSV returned no binary data.'); }
return [{ json: params, binary: { 'AI-Ark_contacts_CSV': data } }];

const item = $input.first();
const form = item.json || {};
const build = ((form['Build name'] || '') + '').trim();
const tid = ((form['Existing Table ID'] || '') + '').trim();
const dtid = ((form['Domains Table ID'] || '') + '').trim();
if (!build && !tid) { throw new Error('Provide a Build name (to create a new table) or an Existing Table ID (to append to one). Nothing was pulled.'); }
if (tid && !/^tbl[A-Za-z0-9]{14}$/.test(tid)) { throw new Error('Existing Table ID "' + tid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was pulled.'); }
if (!dtid) { throw new Error('Provide a Domains Table ID - company data is sourced from it, never guessed or pulled live. Nothing was pulled.'); }
if (!/^tbl[A-Za-z0-9]{14}$/.test(dtid)) { throw new Error('Domains Table ID "' + dtid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was pulled.'); }
return [{ json: Object.assign({}, form, { buildName: build, existingTableId: tid, domainsTableId: dtid, mode: tid ? 'append' : 'create', buildNameIgnored: !!(tid && build) }), binary: item.binary }];

const rows = $input.all().map(i => i.json);
if (!rows.length) { throw new Error('CSV parse returned no rows.'); }
const stripDomain = (url) => {
  let d = String(url || '').trim().toLowerCase();
  if (!d) return '';
  d = d.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  return d;
};
const domains = []; const seen = new Set();
for (const r of rows) {
  const d = stripDomain(r['Company Website']);
  if (d && !seen.has(d)) { seen.add(d); domains.push(d); }
}
return [{ json: { _domains: domains, _domain_count: domains.length, _row_count: rows.length } }];

const g = $('Launch Guard').first().json;
const t = (n) => ({ name: n, type: 'singleLineText' });
const sel = (n, ch) => ({ name: n, type: 'singleSelect', options: { choices: ch.map(c=>({ name: c })) } });
// Fixed contract only - no scanning of the raw AI-Ark CSV for extra columns. Company data
// comes exclusively from the Domains table (whatever fields it actually has); AI-Ark's own
// company columns are dropped entirely, never turned into new table fields.
const fields = [
  t('Name'), t('Contact Key'), t('first_name'), t('last_name'), t('Title'),
  sel('Seniority', ['C-Suite','Founder','Owner','President','Executive','VP','Head','Director','Manager','Senior','Partner','EVP / SVP','Board / Chair','Unclassified']),
  sel('Department', ['Executive','Engineering','Technology','R&D','Product','Data','Security','Design','Operations','Sales','Marketing','Finance','Human Resources','Customer Success','Project Management','Strategy','Legal','Supply Chain','Communications','Community & Social','Compliance & GRC']),
  t('Email'), t('Social'), t('Phone'), t('Connections'), t('Domain'), t('Company'), t('Industry Groups'),
  sel('Employees', ['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+']),
  t('Business Model'), t('MX Provider'),
  t('Description'), t('Keywords'), t('City'), t('State'), t('Country'), t('Zip'), t('Street'),
  sel('Contact Source', ['ContaGen','Supersoniq','AI Ark']),
  t('Tag')
];
const formulaFields = [ { name: 'Build Date', type: 'formula', options: { formula: 'CREATED_TIME()' } } ];
const desiredName = (g.buildName || 'List') + ' - Contacts';
return [{ json: { mode: g.mode, existingTableId: g.existingTableId, buildNameIgnored: !!g.buildNameIgnored, desiredName, fields, formulaFields } }];

const spec = $('Build Table Schema').first().json;
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ': ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const plain = spec.fields || [];
const formulas = spec.formulaFields || [];
if (spec.mode !== 'append') {
  const taken = new Set(tables.map(t => String(t.name)));
  let name = spec.desiredName; let n = 1;
  while (taken.has(name)) { n++; name = spec.desiredName + ' (' + n + ')'; }
  return [{ json: { mode: 'create', createName: name, fields: plain, missing: [], missingNames: [], formulaNames: formulas.map(f => f.name), buildNameIgnored: false } }];
}
const target = tables.find(t => t.id === spec.existingTableId);
if (!target) { throw new Error('Table ' + spec.existingTableId + ' does not exist in base ' + baseId + '. Tables there: ' + tables.map(t => t.name).join(', ') + '. Nothing was written.'); }
if (/domains/i.test(String(target.name || ''))) { throw new Error("Refusing to write contacts into '" + target.name + "' - that table is a domains table. Nothing was written."); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const existing = new Map(targetFields.map(f => [f.name, f]));
const existingCI = new Map(targetFields.map(f => [norm(f.name), f]));
const COMPUTED = new Set(formulas.map(f => f.name));
const kind = (ty) => ty === 'number' ? 'number' : (ty === 'singleSelect' ? 'select' : (ty === 'date' ? 'date' : 'text'));
const okWith = { number: ['number'], text: ['singleLineText','multilineText','singleSelect'], select: ['singleSelect','singleLineText'], date: ['date','dateTime'] };
const contract = plain.concat(formulas);
const clashes = []; const missing = [];
for (const cf of contract) {
  if (COMPUTED.has(cf.name)) {
    const exc = existingCI.get(norm(cf.name));
    if (!exc) { missing.push(cf); continue; }
    if (exc.type !== 'formula') { throw new Error("Table '" + target.name + "' (" + target.id + ') still has a writable ' + cf.name + ' (type: ' + exc.type + '). Convert it to a CREATED_TIME() formula field before building. Nothing was written.'); }
    continue;
  }
  const ex = existing.get(cf.name);
  if (!ex) { missing.push(cf); continue; }
  if (!okWith[kind(cf.type)].includes(ex.type)) { clashes.push(cf.name + ' (type in table: ' + ex.type + ', type expected: ' + cf.type + ')'); }
}
if (clashes.length) { throw new Error("Type clash in table '" + target.name + "' (" + target.id + '): ' + clashes.join('; ') + '. Nothing was written.'); }
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, hasContactKey: existing.has('Contact Key'), fields: contract, missing, missingNames: missing.map(f => f.name), formulaNames: formulas.map(f => f.name), buildNameIgnored: !!spec.buildNameIgnored } }];

const r = $('Table Router').first().json;
let rows = [];
try { rows = $('AT Read Contacts').all().map(i => i.json || {}).filter(x => x && Object.keys(x).length > 0); } catch (e) { rows = []; }
const hasRows = rows.length > 0;
if (hasRows && !r.hasContactKey) { throw new Error("Target table '" + r.tableName + "' has rows but no Contact Key column. Appending contacts here would duplicate instead of dedupe. Nothing was written."); }
return [{ json: Object.assign({}, r, { fieldsCreated: [], targetHasRows: hasRows }) }];

const r = $('Table Router').first().json;
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT Verify Schema').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + baseId + ' after creating fields: ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const target = tables.find(t => t.id === r.tableId);
if (!target) { throw new Error('Table ' + r.tableId + ' is no longer present in base ' + baseId + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const have = new Set(targetFields.map(f => f.name));
const haveCI = new Set(targetFields.map(f => norm(f.name)));
const COMPUTED = new Set(r.formulaNames || []);
const present = (n) => COMPUTED.has(n) ? haveCI.has(norm(n)) : have.has(n);
const still = (r.fields || []).filter(f => !present(f.name)).map(f => f.name);
if (still.length) { throw new Error("Could not create these fields on '" + target.name + "' (" + target.id + '): ' + still.join(', ') + '. Nothing was written.'); }
const wanted = r.missingNames || [];
const created = wanted.filter(n => present(n));
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fieldsCreated: created, buildNameIgnored: !!r.buildNameIgnored, createdFieldError: '' } }];

const j = $input.first().json || {};
if (j && j.mode === 'append') {
  if (!j.tableId) { throw new Error('Table resolution returned no table id: ' + JSON.stringify(j).slice(0,400)); }
  return [{ json: { tableId: j.tableId, tableName: j.tableName, mode: 'append', fieldsCreated: j.fieldsCreated || [], buildNameIgnored: !!j.buildNameIgnored, createdFieldError: j.createdFieldError || '' } }];
}
const ct = $('Created Table Guard').first().json || {};
const bd = $('AT Add Created Formula').first().json || {};
if (!bd.id) { throw new Error("Build Date formula field creation failed on new table '" + (ct.tableName || '') + "' (" + (ct.tableId || '') + '): ' + JSON.stringify(bd).slice(0,400) + '. Nothing was written.'); }
const fieldsCreated = (ct.fieldNames || []).slice().concat(['Build Date']);
return [{ json: { tableId: ct.tableId, tableName: ct.tableName, mode: 'create', fieldsCreated, buildNameIgnored: false, createdFieldError: '' } }];

const j = $('AT Create Table').first().json || {};
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
if (!j.id) { throw new Error('Airtable contacts-table creation failed in base ' + baseId + ': ' + JSON.stringify(j).slice(0,400)); }
return [{ json: { mode: 'create', tableId: j.id, tableName: j.name, fieldNames: (j.fields || []).map(f => f.name) } }];

const items = $input.all().map(i => i.json);
const mapItem = items.find(x => x && x.map);
const map = (mapItem && mapItem.map) || {};
const rows = items.filter(x => x !== mapItem);
const form = $('Contacts Launch').first().json;
const runId = String($execution.id);
const tag = ((form['Tag'] || '') + '').trim();

const stripDomain = (url) => { let d = String(url||'').trim().toLowerCase(); if(!d) return ''; d = d.replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('?')[0]; return d; };

// Decision-maker-tier seniority values, matching the enum used elsewhere in this stack.
const SEN = { c_suite:'C-Suite', vp:'VP', director:'Director', manager:'Manager', senior:'Senior', owner:'Owner', founder:'Founder', head:'Head', partner:'Partner', 'mid-level':'Unclassified', entry:'Unclassified', intern:'Unclassified' };
const mapSeniority = (v) => SEN[String(v||'').trim().toLowerCase()] || 'Unclassified';

// Same company-name cleanup as the Storeleads/Supersoniq pipeline's Format Supersoniq node -
// strips taglines, "Welcome to", legal suffixes, normalizes casing. Applied whether the name
// came from the Domains table match or the AI-Ark CSV fallback.
const cap=(s)=>s?s.charAt(0).toUpperCase()+s.slice(1).toLowerCase():'';
const cleanCompany=(nm)=>{if(!nm)return'';const orig=String(nm).trim();let c=orig.replace(/\s{2,}/g,' ');
const GEN=new Set(['home','welcome','shop','store','about','about us','products','index','page','contact','contact us','blog','news']);
const isGen=(s)=>GEN.has(String(s).trim().toLowerCase());
const TAGLINE_RE=/\b(free|shipping|sale|% ?off|buy now|shop now|official|welcome to|best|discover|explore|save up|subscribe|new arrivals|worldwide|delivery|since \d{4})\b/i;
const looksLikeTagline=(s)=>{const t=String(s||'').trim(); if(!t)return true; if(isGen(t))return true; if(TAGLINE_RE.test(t))return true; return t.split(/\s+/).filter(Boolean).length>=6;};
const pickPair=(head,tail)=>{const h=String(head||'').trim(),t=String(tail||'').trim();
  const hTag=looksLikeTagline(h),tTag=looksLikeTagline(t);
  if(hTag&&tTag)return null;
  if(hTag)return t||null; if(tTag)return h||null;
  if(!h)return t||null; if(!t)return h||null;
  const hw=h.split(/\s+/).length,tw=t.split(/\s+/).length;
  if(Math.abs(hw-tw)<=1)return h;
  return hw<tw?h:t;};
c=c.replace(/^welcome to\s+/i,'').trim();
const pp=c.split(' | ');
if(pp.length>1){
  const cands=pp.map(s=>s.trim()).filter(Boolean);
  const clean=cands.filter(s=>!looksLikeTagline(s));
  if(clean.length===1){c=clean[0];}
  else if(clean.length>1){clean.sort((a,b)=>a.split(/\s+/).length-b.split(/\s+/).length); c=clean[0];}
  else{return orig;}
}
for(let i=0;i<2;i++){const d=c.search(/\s[-–—:]\s/); if(d<3) break; const head=c.slice(0,d).trim(); const tail=c.slice(d).replace(/^\s[-–—:]\s/,'').trim(); const s=pickPair(head,tail); if(s===null) return orig; c=s;}
if(/^[A-Za-z0-9][A-Za-z0-9-]*(\.[A-Za-z]{2,})+$/.test(c)) c=c.replace(/(\.[A-Za-z]{2,})+$/,'');
c=c.replace(/[®™]/g,'');
for(let i=0;i<2;i++){const m=c.match(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i); if(!m)break; const before=c.slice(0,m.index).trim(); const lastWord=before.split(/\s+/).pop()||''; if(lastWord==='&')break; c=before;}
c=c.replace(/,+$/,'').trim();
const hasUp=/\p{Lu}/u.test(c), hasLow=/\p{Ll}/u.test(c);
if(hasUp!==hasLow){const parts=c.split(/(\s+)/); const words=parts.filter(t=>/\S/.test(t)); const MINOR=new Set(['of','and','the','for','to','in','on','at','by','a','an']);
if(!(hasUp&&words.length===1&&c.length<=4)){let wi=-1; c=parts.map(t=>{if(!/\S/.test(t))return t; wi++; const lw=t.toLowerCase(); return (wi>0&&MINOR.has(lw))?lw:lw.replace(/\p{L}/u,(ch)=>ch.toUpperCase());}).join('');}}
return c;};

// Pipeline/bookkeeping fields to never carry through from the Domains table onto a contact -
// same exclusion list as the Storeleads/Supersoniq pipeline's Format Supersoniq node.
const DOMAIN_SKIP = new Set(['domain','company_domain','Verified','segment','query_name','ingested_at','RankInCompany','Run ID','Build Date','Tag','public_emails_clean','Created','Contact Source','Source']);

let skipped = 0;
let matched = 0;
const out = [];
for (const r of rows) {
  const first = String(r['First Name']||'').trim();
  const last = String(r['Last Name']||'').trim();
  const domain = stripDomain(r['Company Website']);
  const key = (first.toLowerCase()+last.toLowerCase()+domain).trim();
  if (!key) { skipped++; continue; }
  const dm = map[domain] || null;
  if (dm) matched++;
  // No match in the Domains table: fall back to AI-Ark's own company name only, nothing else guessed.
  const rawCompany = dm ? (dm.Company || dm.company_clean || '') : String(r['Company Name for Emails']||r['Company Name']||'').trim();
  const company = cleanCompany(rawCompany);

  const dmClean = {};
  if (dm) { for (const k of Object.keys(dm)) { if (DOMAIN_SKIP.has(k)) continue; dmClean[k] = dm[k]; } }

  out.push({ json: {
    ...dmClean,
    'Contact Key': key,
    Name: r['Full Name'] || (first+' '+last).trim(), first_name: first, last_name: last,
    Title: String(r['Title']||''), Seniority: mapSeniority(r['Seniority']),
    Email: String(r['Email Business']||'').trim(), Social: String(r['LinkedIn']||'').trim(), Phone: String(r['Mobile Phone']||'').trim(),
    Domain: domain, Company: company,
    'Contact Source': 'AI Ark', Tag: tag, 'Run ID': runId
  }});
}
const sd = $getWorkflowStaticData('global');
sd.aiArkSkipped = skipped;
sd.aiArkMatched = matched;
if (!out.length) { throw new Error('No usable AI-Ark contacts after formatting. Rows skipped for an empty Contact Key: '+skipped+'.'); }
return out;

const BAN=['Build Date','Run ID','company_clean','Score','Similarity','Valid','Start Date','Redirect Domain','Update Date','MV'];
return $input.all().map(i => { const j = { ...i.json };
  for(const k of BAN) delete j[k];
  return { json: j }; });

const form = $('Contacts Launch').first().json;
const g = $('Contacts Table Guard').first().json || {};
const dg = $('Domains Table Guard').first().json || {};
const written = $('Format AI-Ark').all().length;
const domains = ($('Parse Rows').first().json._domain_count)||0;
const sd = $getWorkflowStaticData('global');
const skipped = Number(sd.aiArkSkipped)||0;
const matched = Number(sd.aiArkMatched)||0;
const tableName = g.tableName||''; const tableId = g.tableId||'';
const modeTxt = (g.mode==='append')?'appended to an existing table':'created a new table';
const fc = (g.fieldsCreated&&g.fieldsCreated.length)?g.fieldsCreated.join(', '):'none';
const tag = ((form['Tag']||'')+'').trim();
const trig = form._launchRecordId?'record':'form';
const started = form.submittedAt||($('Config').first().json||{}).startedAt;
let dur=0; try{ if(started) dur=Math.max(0,Math.round(($now.toMillis()-new Date(started).getTime())/1000)); }catch(e){}
const fmt = v=>Number(v||0).toLocaleString('en-US');
const parts=[];
parts.push('**'+fmt(written)+' AI-Ark contacts upserted across '+fmt(domains)+' domains**');
parts.push('**Tag:** '+(tag||'none'));
parts.push('**Domains table:** '+(dg.domainsTableName||'')+' ('+(dg.domainsTableId||'')+')\n- **Company data matched:** '+fmt(matched)+'\n- **Fell back to name-only:** '+fmt(Math.max(0,domains-matched)));
parts.push('**Rows skipped (empty Contact Key):** '+fmt(skipped));
parts.push('**Table:** '+modeTxt+', '+tableName+' ('+tableId+')\n**Fields created:** '+fc);
if (g.buildNameIgnored) { parts.push('**Warnings (1)**\n- Build name ignored: an Existing Table ID was supplied.'); }
parts.push('**Launched via:** '+trig);
return [{ json: {
  'Automation': 'AI-Ark Export -> Clayroots',
  'Status': 'Succeeded',
  'Trigger': 'form',
  'Errors': 0,
  'Run at': $now.toISO(),
  'Client': form['Clayroots Base ID'],
  'Target': tableName+' ('+tableId+')',
  'Records In': written+skipped,
  'Records Out': written,
  'Duration s': dur,
  'Description': parts.join('\n\n'),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Execution ID': String($execution.id)
} }];

const log = { ...$('Build Log').first().json };
const items = $input.all();
const rec = items.length ? (items[0].json || {}) : {};
const clientId = (typeof rec.id === 'string' && rec.id.startsWith('rec')) ? rec.id : '';
if (clientId) { log.Client = [clientId]; } else { delete log.Client; }
if (!log['Execution ID']) { throw new Error('Fix Client: Build Log payload has no Execution ID. Log row not written.'); }
return [{ json: log }];

const g = $('Launch Guard').first().json;
const baseId = ((g['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ' to verify the Domains table.'); }
const target = tables.find(t => t.id === g.domainsTableId);
if (!target) { throw new Error('Domains Table ID ' + g.domainsTableId + ' does not exist in base ' + baseId + '. Nothing was pulled.'); }
if (!/domains/i.test(String(target.name || ''))) { throw new Error("Table '" + target.name + "' (" + target.id + ") does not look like a Domains table (name must contain 'domains'). Refusing to read company data from it - on purpose, so we never guess the wrong source of truth again. Nothing was pulled."); }
return [{ json: { domainsTableId: target.id, domainsTableName: target.name } }];

// Company data comes ONLY from the given Domains table - the actual source of truth built
// earlier by DiscoLike/Storeleads/whatever else. Never from the Contacts table, never live from an API.
// No hardcoded field list - a Domains table's real schema varies by what built it, so every
// field the record actually has rides through untouched, under whatever name it really has.
const rows = $input.all().map(i => i.json.fields || i.json || {}).filter(r => r && r.Domain);
const map = {};
for (const r of rows) {
  const d = String(r.Domain || '').trim().toLowerCase();
  if (!d || map[d]) continue;
  const co = {};
  for (const k of Object.keys(r)) {
    if (k === 'Domain') continue;
    const v = r[k];
    co[k] = (v===undefined||v===null) ? '' : v;
  }
  map[d] = co;
}
return [{ json: { map } }];
